static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	double sum = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  sum += alpha * A[i][k] * B[k][j];
      tmp[i][j] = (DATA_TYPE)sum;
      }

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	double d_val = (double)D[i][j] * beta;
	for (k = 0; k < _PB_NJ; ++k)
	  d_val += (double)tmp[i][k] * (double)C[k][j];
      D[i][j] = (DATA_TYPE)d_val;
      }
#pragma endscop

}

