static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

  // First GEMM: E = A * B
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      float sum = 0.0f;
      for (k = 0; k < _PB_NK; ++k) {
        sum += A[i][k] * B[k][j];
      }
      E[i][j] = sum;
    }
  }

  // Second GEMM: F = C * D
  for (i = 0; i < _PB_NJ; i++) {
    for (j = 0; j < _PB_NL; j++) {
      float sum = 0.0f;
      for (k = 0; k < _PB_NM; ++k) {
        sum += C[i][k] * D[k][j];
      }
      F[i][j] = sum;
    }
  }

  // Third GEMM: G = E * F
#if defined(__riscv_vector)
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NL; ) {
      size_t vl = __riscv_vsetvl_e32m1(_PB_NL - j);
      DATA_TYPE* g_ptr = &G[i][j];

      // Initialize G[i][j...j+vl-1] to 0
      vfloat32m1_t zero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
      __riscv_vse32_v_f32m1(zero, g_ptr, vl);

      for (k = 0; k < _PB_NJ; ++k) {
        float e_val = E[i][k];
        vfloat32m1_t f_vec = __riscv_vle32_v_f32m1(&F[k][j], vl);
        vfloat32m1_t e_vec = __riscv_vfmv_v_f_f32m1(e_val, vl);
        vfloat32m1_t prod = __riscv_vfmul_vf_vv_f32m1(f_vec, e_vec, vl);
        vfloat32m1_t current_g = __riscv_vle32_v_f32m1(g_ptr, vl);
        vfloat32m1_t next_g = __riscv_vfadd_vv_f32m1(current_g, prod, vl);
        __riscv_vse32_v_f32m1(next_g, g_ptr, vl);
      }
      j += vl;
    }
  }
#else
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NL; j++) {
      float sum = 0.0f;
      for (k = 0; k < _PB_NJ; ++k) {
        sum += E[i][k] * F[k][j];
      }
      G[i][j] = sum;
    }
  }
#endif
#pragma endscop
}

