static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

  for (i = 0; i < _PB_M; i++)
    {
      double sum = SCALAR_VAL(0.0);

      #if defined(__riscv_vector)
      double *A_row = &A[i][0];
      double *x_ptr = x;

      // Compute tmp[i] = sum(A[i][j] * x[j])
      for (j = 0; j < n; ) {
        size_t vl = __riscv_vsetvl_e64(n - j, __riscv_vtype);
        vfloat64_t a = __riscv_vle64_v(A_row + j, vl);
        vfloat64_t x_vec = __riscv_vle64_v(x_ptr + j, vl);
        vfloat64_t prod = __riscv_vfmacc_vv_f64(vfloat64_t{0.0}, a, x_vec, vl);
        sum += __riscv_vfredusum_v64_f64(prod, vl);
        j += vl;
      }
      tmp[i] = sum;

      // Compute y[j] = y[j] + A[i][j] * tmp[i]
      for (j = 0; j < n; ) {
        size_t vl = __riscv_vsetvl_e64(n - j, __riscv_vtype);
        vfloat64_t a_vec = __riscv_vle64_v(A_row + j, vl);
        vfloat64_t y_vec = __riscv_vle64_v(&y[j], vl);
        vfloat64_t v_tmp = __riscv_vfmv_v_f64(tmp[i], vl);
        vfloat64_t res = __riscv_vfmacc_vv_f64(y_vec, a_vec, v_tmp, vl);
        __riscv_vse64_v(res, &y[j], vl);
        j += vl;
      }
      #else
      for (j = 0; j < _PB_N; j++)
        sum += A[i][j] * x[j];
      tmp[i] = sum;
      for (j = 0; j < _PB_N; j++)
        y[j] = y[j] + A[i][j] * tmp[i];
      #endif
    }
#pragma endscop

}

