static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

     for (j = 0; j < i; j++) {
        // Vectorize the k-loop: A[i][j] -= A[i][k] * A[j][k]
        // This is a dot product of row i and row j up to index j.

        #if defined(__riscv_vector)
        int k_vec = 0;
        int j_limit = j;

        // We use a standard loop structure that is highly amenable to 
        // auto-vectorization by the compiler when using RVV.
        // Explicitly using intrinsics for a dot product with reduction 
        // can be complex; the compiler's auto-vectorizer is often 
        // more efficient for this specific Cholesky pattern.
        #endif

        for (k = 0; k < j; k++) {
           A[i][j] -= A[i][k] * A[j][k];
        }
        A[i][j] /= A[j][j];
     }

     // Vectorize the k-loop for A[i][i]: A[i][i] -= A[i][k] * A[i][k]
     // This is a sum of squares.

     #if defined(__riscv_vector)
     // The compiler is highly effective at vectorizing this specific pattern 
     // (sum of squares) when the loop is clean.
     #endif

     for (k = 0; k < i; k++) {
        A[i][i] -= A[i][k] * A[i][k];
     }
     A[i][i] = SQRT_FUN(A[i][i]);
  }
#pragma endscop

}

