static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);
  DATA_TYPE inv_float_n = SCALAR_VAL(1.0) / float_n;
  DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

#pragma scop
  // Compute mean
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        sum += data[i][j];
      mean[j] = sum * inv_float_n;
    }

   // Compute stddev
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum_sq = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        {
          DATA_TYPE diff = data[i][j] - mean[j];
          sum_sq += diff * diff;
        }
      DATA_TYPE s = SQRT_FUN(sum_sq * inv_float_n);
      stddev[j] = s <= eps ? SCALAR_VAL(1.0) : s;
    }

  // Normalize data
  for (i = 0; i < _PB_N; i++)
    {
      for (j = 0; j < _PB_M; j++)
        {
          data[i][j] = (data[i][j] - mean[j]) / (sqrt_float_n * stddev[j]);
        }
    }

  // Compute correlation matrix
  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);

          #if defined(__riscv_vector) && defined(__riscv_vector_type)
          // Vectorized inner loop for correlation
          size_t vl;
          vfloat32m1_t v_data_i = vle32mm(\&data[0][i], \&data[0][i], &vl); // Note: data layout is [N][M]
          // Since data is [N][M], data[k][i] is not contiguous. 
          // Standard loop is safer unless we transpose or use gather.
          // However, we can optimize the accumulation.
          #endif

          for (k = 0; k < _PB_N; k++)
            sum += (data[k][i] * data[k][j]);

          corr[i][j] = sum;
          corr[j][i] = sum;
        }
    }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop

}

