static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop
  // First loop: Compute mean
  for (j = 0; j < _PB_M; j++)
    {
      float sum = 0.0f;
      for (i = 0; i < _PB_N; i++)
        sum += data[i][j];
      mean[j] = sum / float_n;
    }

  // Second loop: Subtract mean
  // Vectorize the inner loop over M
  for (i = 0; i < _PB_N; i++)
    {
#if defined(__riscv_vector)
      for (j = 0; j < _PB_M; ) {
        size_t vl = __riscv_v_ck_mv_f32m1vl(j, _PB_M);
        vfloat32m1_t v_mean = __riscv_v_fre_v_load_u32(&mean[j], vl);
        vfloat32m1_t v_data = __riscv_v_fre_v_load_u32(&data[i][j], vl);
        vfloat32m1_t v_res = __riscv_v_fre_v_sub_vv(v_data, v_mean, vl);
        __riscv_v_fre_v_store_u32(&data[i][j], v_res, vl);
        j += vl;
      }
#else
      for (j = 0; j < _PB_M; j++)
        data[i][j] -= mean[j];
#endif
    }

  // Third loop: Covariance
  // Optimization: Vectorize the inner loop over N (k)
  float inv_n = 1.0f / (float_n - 1.0f);
  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        float sum = 0.0f;
#if defined(__riscv_vector)
        vfloat32m1_t v_sum = __riscv_v_fre_v_zero_f32m1();
        for (k = 0; k < _PB_N; ) {
          size_t vl = __riscv_v_ck_mv_f32m1vl(k, _PB_N);
          // data[k][i] and data[k][j] are accessed. 
          // Since k is the first index, these are strided accesses.
          // We use strided loads to vectorize the k-loop.
          vfloat32m1_t v_data_i = __riscv_v_fre_v_load_u32_strided(&data[k][i], vl, _PB_M);
          vfloat32m1_t v_data_j = __riscv_v_fre_v_load_u32_strided(&data[k][j], vl, _PB_M);
          vfloat32m1_t v_prod = __riscv_v_fre_v_mul_vv(v_data_i, v_data_j, vl);
          v_sum = __riscv_v_fre_v_add_vv(v_sum, v_prod, vl);
          k += vl;
        }
        sum = __riscv_v_fre_v_reduce_add_f32m1(v_sum);
#else
        for (k = 0; k < _PB_N; k++)
          sum += data[k][i] * data[k][j];
#endif

        float val = sum * inv_n;
        cov[i][j] = val;
        cov[j][i] = val;
      }
#pragma endscop

}

