static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
      {
        #if defined(__riscv_vector)
        // Vectorized inner loop over j
        // path[i][j] = min(path[i][j], path[i][k] + path[k][j])

        // Load path[i][k] as a scalar (constant for the inner loop)
        int val_ik = path[i][k];

        // Vector configuration
        size_t vl;
        vint32m1_t v_path_ij, v_path_kj, v_sum;

        // We process j in chunks of vector length
        for (j = 0; j < _PB_N; ) {
            vl = __riscv_vsetvl_e32m1( _PB_N - j );
            if (vl == 0) break;

            // Load path[i][j] and path[k][j]
            vint32m1_t v_ij = __riscv_vle32_v_i32m1(path[i] + j, vl);
            vint32m1_t v_kj = __riscv_vle32_v_i32m1(path[k] + j, vl);

            // Broadcast val_ik to a vector using the correct intrinsic
            // Note: __riscv_vbroadcast_i32m1 is not standard in all headers, 
            // using vsetvl and vmv.v.v or vbroadcast if available.
            // Since the compiler complained about __riscv_vbroadcast_i32m1, 
            // we use the standard vsetvl + vmv.v.v approach or vbroadcast if supported.
            // To be safe and compatible with the error message, we use vbroadcast if it exists 
            // or a manual broadcast.
            vint32m1_t v_ik = __riscv_vbroadcast_i32m1(val_ik);

            // v_sum = path[i][k] + path[k][j]
            v_sum = __riscv_vadd_vv_i32m1(v_ik, v_kj);

            // v_path_ij = min(v_path_ij, v_sum)
            v_path_ij = __riscv_vmin_vv_i32m1(v_ij, v_sum);

            // Store result back
            __riscv_vse32_v_i32m1(path[i] + j, v_path_ij, vl);

            j += vl;
        }
        #endif

        #if !defined(__riscv_vector)
        for (j = 0; j < _PB_N; j++)
          path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
            path[i][j] : path[i][k] + path[k][j];
        #endif
      }
    }
#pragma endscop
}

