static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      C[i][j] *= beta;
    }
    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_val = alpha * A[i][k];

      #if defined(__riscv_vector)
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m1(_PB_NJ - j);

        vfloat32m1_t b_vec = __riscv_vle32_v_f32m1((float*)B[k], j, vl);
        vfloat32m1_t c_vec = __riscv_vle32_v_f32m1((float*)C[i], j, vl);

        vfloat32m1_t prod = __riscv_vfmul_vf_vv_f32m1(b_vec, __riscv_vfmv_v_f32m1_s(a_val, vl));
        vfloat32m1_t res = __riscv_vfadd_vf_vv_f32m1(c_vec, prod);

        __riscv_vse32_v_f32m1((float*)C[i], j, vl, res);
        j += vl;
      }
      #else
      for (j = 0; j < _PB_NJ; j++) {
        C[i][j] += a_val * B[k][j];
      }
      #endif
    }
  }
#pragma endscop

}

