static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  // Loop 1: A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE ui1 = u1[i];
    DATA_TYPE ui2 = u2[i];

    #if defined(__riscv_vector)
    size_t vl;
    for (j = 0; j < _PB_N; ) {
      vl = __riscv_vsetvl_e64m1( _PB_N - j );
      vfloat64m1_t v_v1 = __riscv_vle64_v_f64m1((double*)(v1 + j), vl);
      vfloat64m1_t v_v2 = __riscv_vle64_v_f64m1((double*)(v2 + j), vl);
      vfloat64m1_t v_A = __riscv_vle64_v_f64m1((double*)(A[i] + j), vl);

      vfloat64m1_t v_res1 = __riscv_vfmul_vf_f64m1(v_v1, (double)ui1);
      vfloat64m1_t v_res2 = __riscv_vfmul_vf_f64m1(v_v2, (double)ui2);
      vfloat64m1_t v_sum = __riscv_vfadd_vf_f64m1(v_res1, v_res2);
      vfloat64m1_t v_final = __riscv_vfadd_vf_f64m1(v_A, v_sum);

      __riscv_vse64_v_f64m1((double*)(A[i] + j), v_final, vl);
      j += vl;
    }
    #else
    for (j = 0; j < _PB_N; j++)
      A[i][j] = A[i][j] + ui1 * v1[j] + ui2 * v2[j];
    #endif
  }

  // Loop 2: x[i] = x[i] + beta * A[j][i] * y[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = 0;
    for (j = 0; j < _PB_N; j++) {
      sum += beta * A[j][i] * y[j];
    }
    x[i] += sum;
  }

  // Loop 3: x[i] = x[i] + z[i]
  #if defined(__riscv_vector)
  size_t vl_z;
  for (i = 0; i < _PB_N; ) {
    vl_z = __riscv_vsetvl_e64m1(_PB_N - i);
    vfloat64m1_t v_x = __riscv_vle64_v_f64m1((double*)(x + i), vl_z);
    vfloat64m1_t v_z = __riscv_vle64_v_f64m1((double*)(z + i), vl_z);
    vfloat64m1_t v_res = __riscv_vfadd_vf_f64m1(v_x, v_z);
    __riscv_vse64_v_f64m1((double*)(x + i), v_res, vl_z);
    i += vl_z;
  }
  #else
  for (i = 0; i < _PB_N; i++)
    x[i] = x[i] + z[i];
  #endif

  // Loop 4: w[i] = w[i] + alpha * A[i][j] * x[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE row_sum = 0;
    #if defined(__riscv_vector)
    size_t vl_w;
    for (j = 0; j < _PB_N; ) {
      vl_w = __riscv_vsetvl_e64m1(_PB_N - j);
      vfloat64m1_t v_A = __riscv_vle64_v_f64m1((double*)(A[i] + j), vl_w);
      vfloat64m1_t v_x = __riscv_vle64_v_f64m1((double*)(x + j), vl_w);
      vfloat64m1_t v_prod = __riscv_vfmul_vf_f64m1(v_A, v_x);
      vfloat64m1_t v_sum = __riscv_vfredusum_vf_f64m1(v_prod, vl_w);
      row_sum += (double)__riscv_vfmv_vf_f64m1(v_sum, 1.0); 
      j += vl_w;
    }
    #else
    for (j = 0; j < _PB_N; j++)
      row_sum += A[i][j] * x[j];
    #endif
    w[i] = w[i] + alpha * row_sum;
  }

#pragma endscop
}

