static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);

      // Compute R[k][k]
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];

      R[k][k] = SQRT_FUN(nrm);

      // Compute Q[i][k]
      #if defined(__riscv_vector)
      DATA_TYPE inv_r = 1.0 / R[k][k];
      for (i = 0; i < _PB_M; ) {
          size_t vl = __riscv_v_ck_max();
          if (i + vl > _PB_M) vl = _PB_M - i;
          vfloat32m1_t v_a = __riscv_v_fre_v_f32m1(&A[i][k], vl);
          vfloat32m1_t v_inv = __riscv_v_fre_v_f32m1(&inv_r, vl);
          vfloat32m1_t v_q = __riscv_v_fm_v_f32m1(v_a, v_inv);
          __riscv_v_fe_v_f32m1(&Q[i][k], v_q, vl);
          i += vl;
      }
      #else
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R[k][k];
      #endif

      for (j = k + 1; j < _PB_N; j++)
      {
        R[k][j] = SCALAR_VAL(0.0);

        // Compute R[k][j]
        for (i = 0; i < _PB_M; i++)
          R[k][j] += Q[i][k] * A[i][j];

        // A[i][j] = A[i][j] - Q[i][k] * R[k][j]
        #if defined(__riscv_vector)
        vfloat32m1_t v_rkj = __riscv_v_fre_v_f32m1(&R[k][j], __riscv_v_ck_max());
        for (i = 0; i < _PB_M; ) {
            size_t vl = __riscv_v_ck_max();
            if (i + vl > _PB_M) vl = _PB_M - i;
            vfloat32m1_t v_q = __riscv_v_fre_v_f32m1(&Q[i][k], vl);
            vfloat32m1_t v_a = __riscv_v_fre_v_f32m1(&A[i][j], vl);
            vfloat32m1_t v_prod = __riscv_v_fm_v_f32m1(v_q, v_rkj);
            vfloat32m1_t v_res = __riscv_v_fsub_v_f32m1(v_a, v_prod, vl);
            __riscv_v_fe_v_f32m1(&A[i][j], v_res, vl);
            i += vl;
        }
        #else
        for (i = 0; i < _PB_M; i++)
          A[i][j] = A[i][j] - Q[i][k] * R[k][j];
        #endif
      }
    }
#pragma endscop

}

