static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
#if defined(__riscv_vector)
      const float factor = 0.33333f;
      int num_elements = _PB_N - 2;

      // Process B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1])
      int j = 0;
      while (j < num_elements) {
        size_t vl = __riscv_vsetvl_e32m1(num_elements - j);
        vfloat32m1_t va_prev = __riscv_vle32_v_f32m1((const float*)A + j, vl);
        vfloat32m1_t va_curr = __riscv_vle32_v_f32m1((const float*)A + j + 1, vl);
        vfloat32m1_t va_next = __riscv_vle32_v_f32m1((const float*)A + j + 2, vl);

        // Corrected intrinsic: vfmadd_vv_f32m1(a, b, c) computes (a * b) + c
        // We want (va_curr + va_next + va_prev) * factor.
        // Let's do (va_curr + va_next) + va_prev first.
        vfloat32m1_t sum_tmp = __riscv_vfadd_vv_f32m1(va_curr, va_next, vl);
        vfloat32m1_t sum = __riscv_vfadd_vv_f32m1(sum_tmp, va_prev, vl);

        // Corrected intrinsic: vfmul_vf_f32m1(v, f, vl)
        vfloat32m1_t res = __riscv_vfmul_vf_f32m1(sum, factor, vl);
        __riscv_vse32_v_f32m1(res, (float*)B + j + 1, vl);
        j += vl;
      }

      // Process A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1])
      j = 0;
      while (j < num_elements) {
        size_t vl = __riscv_vsetvl_e32m1(num_elements - j);
        vfloat32m1_t vb_prev = __riscv_vle32_v_f32m1((const float*)B + j, vl);
        vfloat32m1_t vb_curr = __riscv_vle32_v_f32m1((const float*)B + j + 1, vl);
        vfloat32m1_t vb_next = __riscv_vle32_v_f32m1((const float*)B + j + 2, vl);

        vfloat32m1_t sum_tmp = __riscv_vfadd_vv_f32m1(vb_curr, vb_next, vl);
        vfloat32m1_t sum = __riscv_vfadd_vv_f32m1(sum_tmp, vb_prev, vl);

        vfloat32m1_t res = __riscv_vfmul_vf_f32m1(sum, factor, vl);
        __riscv_vse32_v_f32m1(res, (float*)A + j + 1, vl);
        j += vl;
      }
#else
      for (i = 1; i < _PB_N - 1; i++)
        B[i] = 0.33333f * (A[i-1] + A[i] + A[i + 1]);
      for (i = 1; i < _PB_N - 1; i++)
        A[i] = 0.33333f * (B[i-1] + B[i] + B[i + 1]);
#endif
    }
#pragma endscop

}

