static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;
  const float scalar = (float)SCALAR_VAL(0.2);

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      for (i = 1; i < _PB_N - 1; i++)
      {
        #if defined(__riscv_vector)
        int j = 1;
        for (; j <= _PB_N - 2; ) {
          size_t vl = __riscv_vsetvl_e32m1((_PB_N - 2) - j + 1);

          vfloat32m1_t va_curr = __riscv_vle32_v_f32m1(A[i] + j, vl);
          vfloat32m1_t va_left = __riscv_vle32_v_f32m1(A[i] + j - 1, vl);
          vfloat32m1_t va_right = __riscv_vle32_v_f32m1(A[i] + j + 1, vl);
          vfloat32m1_t va_down = __riscv_vle32_v_f32m1(A[i+1] + j, vl);
          vfloat32m1_t va_up = __riscv_vle32_v_f32m1(A[i-1] + j, vl);

          vfloat32m1_t v_sum = __riscv_vfadd_vv(va_curr, va_left, vl);
          v_sum = __riscv_vfadd_vv(v_sum, va_right, vl);
          v_sum = __riscv_vfadd_vv(v_sum, va_down, vl);
          v_sum = __riscv_vfadd_vv(v_sum, va_up, vl);

          vfloat32m1_t v_res = __riscv_vf_vmul_vf_f32m1(v_sum, scalar, vl);
          __riscv_vse32_v_f32m1(B[i] + j, v_res, vl);

          j += (int)vl;
        }
        for (; j < _PB_N - 1; j++) {
          B[i][j] = scalar * (A[i][j] + A[i][j-1] + A[i][j+1] + A[i+1][j] + A[i-1][j]);
        }
        #else
        for (j = 1; j < _PB_N - 1; j++)
          B[i][j] = scalar * (A[i][j] + A[i][j-1] + A[i][j+1] + A[i+1][j] + A[i-1][j]);
        #endif
      }

      for (i = 1; i < _PB_N - 1; i++)
      {
        #if defined(__riscv_vector)
        int j = 1;
        for (; j <= _PB_N - 2; ) {
          size_t vl = __riscv_vsetvl_e32m1((_PB_N - 2) - j + 1);

          vfloat32m1_t vb_curr = __riscv_vle32_v_f32m1(B[i] + j, vl);
          vfloat32m1_t vb_left = __riscv_vle32_v_f32m1(B[i] + j - 1, vl);
          vfloat32m1_t vb_right = __riscv_vle32_v_f32m1(B[i] + j + 1, vl);
          vfloat32m1_t vb_down = __riscv_vle32_v_f32m1(B[i+1] + j, vl);
          vfloat32m1_t vb_up = __riscv_vle32_v_f32m1(B[i-1] + j, vl);

          vfloat32m1_t v_sum = __riscv_vfadd_vv(vb_curr, vb_left, vl);
          v_sum = __riscv_vfadd_vv(v_sum, vb_right, vl);
          v_sum = __riscv_vfadd_vv(v_sum, vb_down, vl);
          v_sum = __riscv_vfadd_vv(v_sum, vb_up, vl);

          vfloat32m1_t v_res = __riscv_vf_vmul_vf_f32m1(v_sum, scalar, vl);
          __riscv_vse32_v_f32m1(A[i] + j, v_res, vl);

          j += (int)vl;
        }
        for (; j < _PB_N - 1; j++) {
          A[i][j] = scalar * (B[i][j] + B[i][j-1] + B[i][j+1] + B[i+1][j] + B[i-1][j]);
        }
        #else
        for (j = 1; j < _PB_N - 1; j++)
          A[i][j] = scalar * (B[i][j] + B[i][j-1] + B[i][j+1] + B[i+1][j] + B[i-1][j]);
        #endif
      }
    }
#pragma endscop
}

