static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  // Optimization for first loop: x1[i] = x1[i] + sum_j(A[i][j] * y_1[j])
  // This is a Matrix-Vector multiplication (Row-major access for A)
  for (i = 0; i < _PB_N; i++) {
    float sum = 0.0f;
    for (j = 0; j < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e32m1(_PB_N - j);
      vfloat32m1_t va = __riscv_vle32_v_f32m1((const float*)&A[i][j], vl);
      vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float*)&y_1[j], vl);
      vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(va, vy, vl);

      vfloat32m1_t vsum = __riscv_vfredusum_vf32m1(vprod, vl);
      sum += __riscv_vfmv_x_f32m1_s(vsum, vl);
      j += (int)vl;
    }
    x1[i] += sum;
  }

  // Optimization for second loop: x2[i] = x2[i] + sum_j(A[j][i] * y_2[j])
  // A[j][i] is not contiguous. We use strided loads.
  for (i = 0; i < _PB_N; i++) {
    float sum = 0.0f;
    for (j = 0; j < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e32m1(_PB_N - j);
      // A[j][i] is separated by _PB_N elements. 
      // We use a strided load where the stride is the row length.
      vfloat32m1_t va = __riscv_vlseg32_v_f32m1((const float*)&A[0][i], _PB_N, vl);
      vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float*)&y_2[j], vl);
      vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(va, vy, vl);

      vfloat32m1_t vsum = __riscv_vfredusum_vf32m1(vprod, vl);
      sum += __riscv_vfmv_x_f32m1_s(vsum, vl);
      j += (int)vl;
    }
    x2[i] += sum;
  }
#pragma endscop

}

