static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      x[i] = b[i];

      #if defined(__riscv_vector)
      int j = 0;
      // Since DATA_TYPE is double (based on the compiler error), 
      // we use e64 (64-bit) vector types.
      for (; j < i; ) {
        size_t vl = __riscv_vsetvl_e64m1(i - j);

        vfloat64m1_t v_l = __riscv_vle64_v_f64m1((const double*)&L[i][j], vl);
        vfloat64m1_t v_x = __riscv_vle64_v_f64m1((const double*)&x[j], vl);
        vfloat64m1_t v_prod = __riscv_vfmul_vv_f64m1(v_l, v_x, vl);
        vfloat64m1_t v_sum = __riscv_vfredusum_vs_f64m1(v_prod, vl);

        x[i] -= __riscv_vfmv_x_f64m1_s_f64(v_sum, vl);
        j += vl;
      }
      #else
      for (j = 0; j < i; j++)
        x[i] -= L[i][j] * x[j];
      #endif

      x[i] = x[i] / L[i][i];
    }
#pragma endscop

}

